(* [comment removed for export] *)
Definition gcw (c0 c1 c2 c3 : Z) : Z := u32le c0 c1 c2 c3 + hi32 c3 * 2^32.
Lemma gcw_range : forall c0 c1 c2 c3, 0 <= c0 < 256 -> 0 <= c1 < 256 -> 0 <= c2 < 256 -> 0 <= c3 < 256 -> 0 <= gcw c0 c1 c2 c3 < 2^64.
Proof. intros. unfold gcw. pose proof (u32le_range c0 c1 c2 c3). pose proof (hi32_range c3). lia. Qed.
Lemma gcw_eqw : forall c0 c1 c2 c3, 0 <= c0 < 256 -> 0 <= c1 < 256 -> 0 <= c2 < 256 -> 0 <= c3 < 256 ->
  gcw c0 c1 c2 c3 = eqw_code c0 c1 c2 c3.
Proof. intros. unfold gcw. symmetry. apply eqw_code_split; lia. Qed.

Lemma shl_byte_range : forall c k, 0 <= c < 256 -> 0 <= k <= 24 -> 0 <= Z.shiftl c k < 2^32.
Proof.
  intros c k Hc Hk. rewrite Z.shiftl_mul_pow2 by lia. split. { apply Z.mul_nonneg_nonneg; [lia|]. apply Z.pow_nonneg. lia. }
  apply (Z.lt_le_trans _ (256 * 2^k)). { apply Z.mul_lt_mono_pos_r; [apply Z.pow_pos_nonneg; lia | lia]. }
  change 256 with (2^8). rewrite <- Z.pow_add_r by lia. apply Z.pow_le_mono_r; lia.
Qed.
Lemma ulit_shl : forall c k, 0 <= c < 256 -> 0 <= k <= 24 ->
  bv_unsigned (Z_to_bv 64 (Z.shiftl (bv_unsigned (Z_to_bv 64 c)) k)) = Z.shiftl c k.
Proof.
  intros c k Hc Hk. rewrite (unsigned_lit c) by lia. pose proof (shl_byte_range c k Hc Hk). apply unsigned_lit. lia.
Qed.
Lemma ulit_lor32 : forall a b, 0 <= a < 2^32 -> 0 <= b < 2^32 -> bv_unsigned (Z_to_bv 64 (Z.lor a b)) = Z.lor a b.
Proof. intros a b Ha Hb. pose proof (lor_small a b 32 Ha Hb ltac:(lia)). apply unsigned_lit. lia. Qed.

Lemma ulit_M64 : forall z, bv_unsigned (Z_to_bv 64 z) = Z.land z M64.
Proof. intros. rewrite unsigned_lit_wrap. change M64 with (Z.ones 64). rewrite Z.land_ones by lia. reflexivity. Qed.

