Section DIG.
  Context {HCEIL : HeapCeil}.

Definition P_B_FT_GETCHARS : Z := 0xbf4e0.     (* [comment removed for export] *)
Definition AGC_STACK : Z := 16.
Definition ADIG_STACK : Z := 80 + AGC_STACK.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition getchars_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (bs : list byte) (b0 b1 b2 b3 : byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (gcw (zb b0) (zb b1) (zb b2) (zb b3))) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ bytes_at bsegs m' P bs
    /\ ACONST m' /\ accessible m' P (Z.of_nat (length bs)).

(* [comment removed for export] *)
Definition getchars_stmt : Prop :=
  forall (P lo : Z) (bs : list byte) (j : nat) (b0 b1 b2 b3 : byte)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  bytes_at bsegs m P bs -> P + Z.of_nat (length bs) < 2^64 -> 0 < P ->
  nth_error bs j = Some b0 -> nth_error bs (S j) = Some b1 -> nth_error bs (S (S j)) = Some b2 -> nth_error bs (S (S (S j))) = Some b3 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + AGC_STACK <= bv_unsigned sp -> aceil <= lo ->
  (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo) ->
  mem_inv bsegs m ->
  ACONST m -> accessible m P (Z.of_nat (length bs)) ->
  evt bsegs (getchars_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo bs b0 b1 b2 b3 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (P + Z.of_nat j)) a1 a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_FT_GETCHARS) fc None m (seg_rom bsegs)).

(* [comment removed for export] *)
Definition dig_post_v (v : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (bv_swrap 32 v)) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ bytes_at bsegs m' P bs
    /\ ACONST m' /\ accessible m' P (Z.of_nat (length bs)).

Definition digest_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  dig_post_v (ft_digest (zbytes bs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo bs m.

Definition digest_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P lo : Z) (bs : list byte),
  bytes_at bsegs m P bs -> P + Z.of_nat (length bs) < 2^64 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + ADIG_STACK <= bv_unsigned sp -> aceil <= lo ->      (* [comment removed for export] *)
  (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo) ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m -> accessible m P (Z.of_nat (length bs)) ->
  (* [comment removed for export] *)
  (0 < Z.of_nat (length bs) -> 0 < P) ->
  evt bsegs (digest_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo bs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz (Z.of_nat (length bs))) a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FIELD_TABLE_DIGEST) fc None m (seg_rom bsegs)).

(* [comment removed for export] *)
Definition dg_side (m : mem) (P n : Z) : Prop := ACONST m /\ accessible m P n.
Lemma dg_side_now : forall m m1 P n lo hi,
  dg_side m P n -> munch [(lo, hi)]%Z m m1 -> wmono bsegs m m1 -> aceil <= lo -> dg_side m1 P n.
Proof.
  intros m m1 P n lo hi (AC & AW) MU WM CEIL.
  assert (FW : Forall awin [(lo, hi)]%Z) by (apply Forall_cons; [apply awin_stack; exact CEIL| apply Forall_nil]).
  split; [eapply aconst_transport_awin; eassumption| eapply acc_transport_awin; eassumption].
Qed.

(* [comment removed for export] *)
Definition dig_ctx (m m1 : mem) (sp rav s0v s1v s2v s3v s4v s5v s6v s7v : word) (j8 : list byte) (P lo : Z) (bs : list byte) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -80) [CB 8 j8; C8 s7v; C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ bytes_at bsegs m1 P bs
  /\ stk bsegs m1 lo (bv_unsigned sp + -80)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ dg_side m P (Z.of_nat (length bs)).

Definition dig_pure (sp : word) (P lo : Z) (bs : list byte) : Prop :=
