Lemma dig_exit : forall (v : Z) rax ra sp gp tp t0 t1 t2 s0x a0 a1 a2 a3 a4 a5 a6 a7 s2x s3x s4x s5x s6x s7x
    s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6 (j8 : list byte)
    (F : bvmap 5 word) fc (m m1 : mem) (P lo : Z) (bs : list byte),
  dig_ctx m m1 sp ra s0v s1v s2v s3v s4v s5v s6v s7v j8 P lo bs -> dig_pure sp P lo bs ->
  evt bsegs (dig_post_v v ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P lo bs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 s0x (Z_to_bv 64 (bv_swrap 32 v)) a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6)
